from __future__ import absolute_import

from taf.selenium.gnb.oam.coam.cu.pages.LoginPage import CoamCULoginPage


class ViewPanel(CoamCULoginPage):
    _DETAIL_PANEL_XPATH = "//details-panel[@documentation='details']//" \
                          "wf-panel[@panel-name='admin.common.detailsPanel.TITLE']"

    def show_detail_panel(self, xpath, index=0):
        self.click_and_wait_for_corresponding_element_visible(xpath, self._DETAIL_PANEL_XPATH, index)

    def _verify_toast_message_return_status(self, message, timeout):
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format(message), timeout)
        self.wait_for_invisibility(self.locator.TOAST_MESSAGE.format(message), timeout)
        return self.get_text(self.locator.TOAST_MESSAGE_CONTAINER, timeout)
